    expect(await labelOf(await byLabelStartsWith('רמת התחזקות: '))).toBe('רמת התחזקות: כל יום. מעבר לשלב כדי לשנות');

    // 4. «נוסח תפילה»: ровно 2 варианта «נוסח אשכנז» и «נוסח ספרד / עדות המזרח» с пояснениями, нет отдельного «עדות המזרח · בקרוב»
    //    (#32e3cd9a, עבר QA 21.10; Figma S-07 444:1283). Закрыть без сохранения.
    await scrollToText('נוסח תפילה');
    await (await byLabelStartsWith('נוסח תפילה: ')).click();
    expect(await checked(await byLabelStartsWith('נוסח אשכנז'))).toBe(true);
    expect(await checked(await byLabelStartsWith('נוסח ספרד'))).toBe(false);
    await expect(byLabelStartsWith('נוסח ספרד / עדות המזרח')).toBeExisting();
    await expect(byTextContains('נוסח התפילה האשכנזי המסורתי')).toBeExisting();
    await expect(byTextContains('נוסח התפילה הספרדי והעדות המזרח')).toBeExisting();
    await expect(byLabelStartsWith('נוסח עדות המזרח')).not.toBeExisting();
